interpolate3(INT16 out[3], const INT16 a[3], const INT16 b[3], INT16 shift) {
    out[0] = (a[0] * ((1 << SHIFT_BITS) - shift) + b[0] * shift) >> SHIFT_BITS;
    out[1] = (a[1] * ((1 << SHIFT_BITS) - shift) + b[1] * shift) >> SHIFT_BITS;
    out[2] = (a[2] * ((1 << SHIFT_BITS) - shift) + b[2] * shift) >> SHIFT_BITS;
}

static inline void
interpolate4(INT16 out[4], const INT16 a[4], const INT16 b[4], INT16 shift) {
    out[0] = (a[0] * ((1 << SHIFT_BITS) - shift) + b[0] * shift) >> SHIFT_BITS;
    out[1] = (a[1] * ((1 << SHIFT_BITS) - shift) + b[1] * shift) >> SHIFT_BITS;
    out[2] = (a[2] * ((1 << SHIFT_BITS) - shift) + b[2] * shift) >> SHIFT_BITS;
    out[3] = (a[3] * ((1 << SHIFT_BITS) - shift) + b[3] * shift) >> SHIFT_BITS;
}

static inline int
table_index3D(int index1D, int index2D, int index3D, int size1D, int size1D_2D) {
    return index1D + index2D * size1D + index3D * size1D_2D;
}

#if defined(__SSE4_2__)
/* SSE2-based linear interpolation between two cells of up to 4 INT16 channels.
   The lower 4 INT16 lanes of a and b hold the cell values; the result is
   placed in the lower 4 INT16 lanes of the returned register.
   ((a * (Q - shift) + b * shift) >> SHIFT_BITS) per channel, where
   Q = 1 << SHIFT_BITS. */
static inline __m128i
mm_lerp_int16(__m128i a, __m128i b, __m128i interleaved_coeffs) {
    __m128i interleaved = _mm_unpacklo_epi16(a, b);
    __m128i product = _mm_madd_epi16(interleaved, interleaved_coeffs);
    __m128i shifted = _mm_srai_epi32(product, SHIFT_BITS);
    return _mm_packs_epi32(shifted, shifted);
}

/* Build the interleaved [Q-s, s, Q-s, s, ...] coefficient vector. */
static inline __m128i
mm_lerp_coeffs(INT16 shift) {
    __m128i s_v = _mm_set1_epi16(shift);
    __m128i one_minus_s_v = _mm_set1_epi16((INT16)((1 << SHIFT_BITS) - shift));
    return _mm_unpacklo_epi16(one_minus_s_v, s_v);
}
#endif

