ImagingPackRGB(UINT8 *out, const UINT8 *in, int pixels) {
    int i = 0;
    /* RGB triplets */
#ifdef __sparc
    /* SPARC CPUs cannot read integers from nonaligned addresses. */
    for (; i < pixels; i++) {
        out[0] = in[R];
        out[1] = in[G];
        out[2] = in[B];
        out += 3;
        in += 4;
