/* Determine an appropriate OpenMP thread count for this process.
   Honors OMP_NUM_THREADS if set; otherwise probes (in order):
     - cgroup v2 cpu.max
     - cgroup v1 cpu.cfs_quota_us / cpu.cfs_period_us
     - sched_getaffinity()
   The result is cached and capped at a sane upper bound. */
static int
_lut_thread_count(void) {
    static int cached = 0;
    if (cached != 0) {
        return cached;
    }
    int n = 0;

    const char *env = getenv("OMP_NUM_THREADS");
    if (env != NULL && *env != '\0') {
        n = atoi(env);
    }
    if (n <= 0) {
        FILE *f = fopen("/sys/fs/cgroup/cpu.max", "r");
        if (f != NULL) {
            char buf[64];
            if (fgets(buf, sizeof(buf), f) != NULL) {
                long quota = 0, period = 0;
                if (sscanf(buf, "%ld %ld", &quota, &period) == 2 &&
                    quota > 0 && period > 0) {
                    n = (int)((quota + period - 1) / period);
                }
            }
            fclose(f);
        }
    }
    if (n <= 0) {
        FILE *fq = fopen("/sys/fs/cgroup/cpu/cpu.cfs_quota_us", "r");
        if (fq != NULL) {
            long quota = -1;
            if (fscanf(fq, "%ld", &quota) == 1 && quota > 0) {
                FILE *fp = fopen("/sys/fs/cgroup/cpu/cpu.cfs_period_us", "r");
                if (fp != NULL) {
                    long period = 0;
                    if (fscanf(fp, "%ld", &period) == 1 && period > 0) {
                        n = (int)((quota + period - 1) / period);
                    }
                    fclose(fp);
                }
            }
            fclose(fq);
        }
    }
#ifdef __linux__
    if (n <= 0) {
        cpu_set_t mask;
        CPU_ZERO(&mask);
        if (sched_getaffinity(0, sizeof(mask), &mask) == 0) {
            n = CPU_COUNT(&mask);
        }
    }
#endif
    if (n <= 0) {
        n = omp_get_num_procs();
    }
    if (n <= 0) {
        n = 1;
    }
    if (n > 16) {
        n = 16;
    }
    cached = n;
    return n;
}
#endif

