#include "Imaging.h"
#include "ImagingThreads.h"

int
ImagingRawEncode(Imaging im, ImagingCodecState state, UINT8 *buf, int bytes) {
    UINT8 *ptr;

    if (!state->state) {
        /* The "count" field holds the stride, if specified.  Fix
           things up so "bytes" is the full size, and "count" the
           packed size */

        if (state->count > 0) {
            int bytes = state->count;

            /* stride must not be less than real size */
            if (state->count < state->bytes) {
                state->errcode = IMAGING_CODEC_CONFIG;
                return -1;
            }
            state->count = state->bytes;
            state->bytes = bytes;
        } else {
            state->count = state->bytes;
        }

        /* The "ystep" field specifies the orientation */

        if (state->ystep < 0) {
            state->y = state->ysize - 1;
            state->ystep = -1;
        } else {
            state->ystep = 1;
        }

        state->state = 1;
    }

    if (bytes < state->bytes) {
        state->errcode = IMAGING_CODEC_CONFIG;
        return 0;
    }

    ptr = buf;

    /* Determine how many rows we can process in this call. */
    int rows_remaining = (state->ystep > 0) ? (state->ysize - state->y)
                                            : (state->y + 1);
    int rows_capacity = bytes / state->bytes;
    int rows = rows_remaining < rows_capacity ? rows_remaining : rows_capacity;

    if (rows > 1) {
        int y0 = state->y;
        int ystep = state->ystep;
        int xoff = state->xoff;
        int yoff = state->yoff;
        int xsize = state->xsize;
        int row_bytes = state->bytes;
        int row_count = state->count;
        ImagingShuffler shuffle = state->shuffle;
        int pixelsize = im->pixelsize;

#ifdef _OPENMP
        #pragma omp parallel for schedule(static)
#endif
        for (int i = 0; i < rows; i++) {
            UINT8 *row_out = ptr + (Py_ssize_t)i * row_bytes;
            int y = y0 + ystep * i;
            shuffle(
                row_out,
                (UINT8 *)im->image[y + yoff] + xoff * pixelsize,
                xsize);
            if (row_bytes > row_count) {
                memset(row_out + row_count, 0, row_bytes - row_count);
            }
        }

        ptr += (Py_ssize_t)rows * row_bytes;
        bytes -= rows * row_bytes;
        state->y = y0 + ystep * rows;

        if (state->y < 0 || state->y >= state->ysize) {
            state->errcode = IMAGING_CODEC_END;
            return ptr - buf;
        }
    }

    while (bytes >= state->bytes) {
        state->shuffle(
            ptr,
            (UINT8 *)im->image[state->y + state->yoff] + state->xoff * im->pixelsize,
            state->xsize);

        if (state->bytes > state->count) {
