                __m128i coeffs2 = _mm_set1_epi16(shift2D);
                __m128i coeffs3 = _mm_set1_epi16(shift3D);

                __m128i c000 = _mm_loadl_epi64((const __m128i *)&table[idx]);
                __m128i c100 = _mm_loadl_epi64((const __m128i *)&table[idx + 3]);
                __m128i c010 = _mm_loadl_epi64((const __m128i *)&table[idx + stride1]);
                __m128i c110 =
                    _mm_loadl_epi64((const __m128i *)&table[idx + stride1 + 3]);
                __m128i c001 = _mm_loadl_epi64((const __m128i *)&table[idx + stride2]);
