96	ImagingColorLUT3D_linear(
97	    Imaging imOut,
98	    Imaging imIn,
99	    int table_channels,
100	    int size1D,
101	    int size2D,
102	    int size3D,
103	    INT16 *table) {
104	    /* This float to int conversion doesn't have rounding
105	       error compensation (+0.5) for two reasons:
106	       1. As we don't hit the highest value,
107	          we can use one extra bit for precision.
108	       2. For every pixel, we interpolate 8 elements from the table:
109	          current and +1 for every dimension and their combinations.
110	          If we hit the upper cells from the table,
111	          +1 cells will be outside of the table.
112	          With this compensation we never hit the upper cells
113	          but this also doesn't introduce any noticeable difference. */
114	    UINT32 scale1D = (size1D - 1) / 255.0 * (1 << SCALE_BITS);
115	    UINT32 scale2D = (size2D - 1) / 255.0 * (1 << SCALE_BITS);
116	    UINT32 scale3D = (size3D - 1) / 255.0 * (1 << SCALE_BITS);
117	    int size1D_2D = size1D * size2D;
118	    int y;
119	    ImagingSectionCookie cookie;
120	
121	    if (table_channels < 3 || table_channels > 4) {
122	        PyErr_SetString(PyExc_ValueError, "table_channels could be 3 or 4");
